// #94c3ab (6a993d738eac0db9d694c3ab) «פיתוח: ניהול גרסאות וסטטוסים של סימולציה» — ТОЛЬКО ЧТЕНИЕ и отказы сервера на несуществующую симуляцию.
// STAT-006: шапка готового отчёта «סימולציה «…» · גרסה N» (AC5). STAT-007/008: create_candidate и save_simulation на несуществующий id → 400
// (сервер отказывает до записи; тест проверяет, что ничего не создалось). Звонки не стартуют, статусы не меняются, квота не тратится.
// Не автоматизировано (нужен настоящий официальный звонок и реальная запертая симуляция): active→locked→active, simulation_locked,
// simulation_not_active с hint locked на настоящем id.
import { test, expect } from '@playwright/test';
import { openWithApi, runStamp } from '../support/api';
import { HASH, MANAGER_STATE, NO_SUCH_SIMULATION } from './support';

test.use({ storageState: MANAGER_STATE });

type Row = { id: string; full_name: string; report_status: string | null; personal_data_erased?: boolean; simulation: { id: string; name: string; version: number } | null };

test.describe(`Статусы симуляции — отчёт и серверные отказы, только чтение (${HASH})`, () => {
  test(`STAT-006: готовый отчёт — шапка «סימולציה «<имя>» · גרסה <N>» (имя и версия на момент выполнения) @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const res = await api.rpc('list_candidates');
    expect(res.status(), await res.text()).toBe(200);
    const rows = (await res.json()) as Row[];
    const wanted = process.env.QA_94C3AB_CANDIDATE;
    const c = rows.find((r) => (wanted ? r.full_name === wanted : r.report_status === 'ready' && !r.personal_data_erased && r.simulation));
    test.skip(!c, 'окружение: у testim нет кандидата с готовым отчётом');

    await page.goto(`/candidates/${c!.id}/report`);
    await expect(page.getByTestId('report-summary')).toBeAttached({ timeout: 30_000 });

    // Источник: AC5, דרישה 4 «הדוח מציג את שם הסימולציה והגרסה»; Figma 678:654.
    const expected = `סימולציה «${c!.simulation!.name}» · גרסה ${c!.simulation!.version}`;
    await expect(page.locator('main')).toContainText(expected);
  });

  test(`STAT-007: сервер — create_candidate на несуществующую симуляцию → 400, кандидат не создан @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const name = `QA-AUTO-${runStamp()} fake-sim`;
    const res = await api.rpc('create_candidate', {
      p_fields: { full_name: name, phone: '0000000000', role_title: 'QA-AUTO נציג/ת', simulation_id: NO_SUCH_SIMULATION, assigned_manager_id: await api.userId() },
    });
    // Источник: דרישה 6 «נעולה/לא פעילה חוסמת שיוך», CAND-002 (simulation_not_active): серверная проверка, не только UI.
    const body = await res.text();
    test.info().annotations.push({ type: 'server-answer', description: body.slice(0, 200) });
    expect(res.status(), body).toBe(400);
    const found = await (await api.get(`candidates?select=id&full_name=eq.${encodeURIComponent(name)}`)).json();
    expect(found, 'кандидат не должен быть создан').toEqual([]);
  });

  test(`STAT-008: сервер — save_simulation на несуществующий id → 400, симуляция не создана и не изменена @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/simulations');
    const res = await api.rpc('save_simulation', { p_simulation_id: NO_SUCH_SIMULATION, p_fields: { name: `QA-AUTO-${runStamp()} fake-sim` } });
    // Источник: דרישה 2/5 — запись возможна только для существующей редактируемой симуляции (draft или активная версия).
    const body = await res.text();
    test.info().annotations.push({ type: 'server-answer', description: body.slice(0, 200) });
    expect(res.status(), body).toBe(400);
    const found = await (await api.get(`simulations?select=id&id=eq.${NO_SUCH_SIMULATION}`)).json();
    expect(found, 'симуляция не должна появиться').toEqual([]);
  });
});
